1	/* U5 contract (ROADMAP_LINUX_RUNTIME.md): fopen/fwrite/fclose then fopen/
2	 * fseek/ftell/fread/fclose exercise openat/write/close/lseek/read/fstat
3	 * through ordinary glibc stdio. Explicit syscall() probes cover the rest
4	 * of the roadmap's "File I/O syscall set" directly and deterministically
5	 * (stdio alone does not necessarily reach fstatat/statx/faccessat/getcwd/
6	 * pread64/readlinkat/getdents64).
7	 *
8	 * _GNU_SOURCE: struct statx/STATX_* and SYS_statx are declared only under
9	 * __USE_GNU (glibc's sys/stat.h), not implied by -std=gnu11 alone.
10	 */
11	#define _GNU_SOURCE
12	#include <errno.h>
13	#include <fcntl.h>
14	#include <stdio.h>
15	#include <string.h>
16	#include <sys/stat.h>
17	#include <sys/syscall.h>
18	#include <unistd.h>
19	
20	int main(void)
21	{
22	  /* Unbuffered stdout: isatty(1) is false here (no tty ioctl exists on
23	   * this relay), so glibc fully-buffers stdout by default and every
24	   * printf below would sit unflushed until exit() -- which, per
25	   * ROADMAP_LINUX_RUNTIME.md U4's documented gap, may never get that far.
26	   * _exit() below (not return/exit()) is the other half of routing around
27	   * that unrelated, already-tracked issue: this fixture tests U5's file
28	   * I/O, not U4's exit()-handler-list bug. */
29	  setvbuf(stdout, NULL, _IONBF, 0);
30	
31	  const char* path = "rt_linux_file_test.tmp";
32	  const char payload[] = "0123456789abcdefghijklmnopqrstuvwxyz";
33	
34	  FILE* f = fopen(path, "w");
35	  if (!f) {
36	    printf("FILEIO: fopen(w) failed\n");
37	    _exit(1);
38	  }
39	  if (fwrite(payload, 1, sizeof payload, f) != sizeof payload) {
40	    printf("FILEIO: short write\n");
41	    _exit(1);
42	  }
43	  fclose(f);
44	
45	  f = fopen(path, "r");
46	  if (!f) {
47	    printf("FILEIO: fopen(r) failed\n");
48	    _exit(1);
49	  }
50	  if (fseek(f, 0, SEEK_END) != 0) {
51	    printf("FILEIO: fseek(END) failed\n");
52	    _exit(1);
53	  }
54	  long size = ftell(f);
55	  if (size != (long) sizeof payload) {
56	    printf("FILEIO: ftell=%ld want %u\n", size, (unsigned) sizeof payload);
57	    _exit(1);
58	  }
59	  if (fseek(f, 0, SEEK_SET) != 0) {
60	    printf("FILEIO: fseek(SET) failed\n");
61	    _exit(1);
62	  }
63	
64	  char back[sizeof payload];
65	  memset(back, 0, sizeof back);
66	  size_t r = fread(back, 1, sizeof back, f);
67	  fclose(f);
68	  if (r != sizeof payload || memcmp(payload, back, sizeof payload) != 0) {
69	    printf("FILEIO: readback mismatch (%u)\n", (unsigned) r);
70	    _exit(1);
71	  }
72	  printf("FILEIO: stdio size=%ld ok\n", size);
73	
74	  /* Direct syscall probes: the rest of the roadmap's File I/O set. open()
75	   * on riscv64 compiles down to openat(AT_FDCWD, ...) too -- same syscall,
76	   * already proven by the stdio path above, reused here for a plain fd. */
77	  int fd = open(path, O_RDONLY);
78	  if (fd < 0) {
79	    printf("FILEIO: open failed\n");
80	    _exit(1);
81	  }
82	
83	  struct stat st;
84	  if (fstat(fd, &st) != 0 || st.st_size != (long) sizeof payload) {
85	    printf("FILEIO: fstat failed or wrong size\n");
86	    _exit(1);
87	  }
88	  printf("FILEIO: fstat size=%ld ok\n", (long) st.st_size);
89	
90	  char buf4[4];
91	  long pr = syscall(SYS_pread64, fd, buf4, 4, 4);
92	  if (pr != 4 || memcmp(buf4, payload + 4, 4) != 0) {
93	    printf("FILEIO: pread64 failed\n");
94	    _exit(1);
95	  }
96	  printf("FILEIO: pread64 ok\n");
97	  close(fd);
98	
99	  struct stat st2;
100	  if (syscall(SYS_newfstatat, AT_FDCWD, path, &st2, 0) != 0 ||
101	      st2.st_size != (long) sizeof payload) {
102	    printf("FILEIO: fstatat failed\n");
103	    _exit(1);
104	  }
105	  printf("FILEIO: fstatat ok\n");
106	
107	#ifdef SYS_statx
108	  struct statx stx;
109	  memset(&stx, 0, sizeof stx);
110	  if (syscall(SYS_statx, AT_FDCWD, path, 0, STATX_BASIC_STATS, &stx) != 0 ||
111	      stx.stx_size != (unsigned long) sizeof payload) {
112	    printf("FILEIO: statx failed\n");
113	    _exit(1);
114	  }
115	  printf("FILEIO: statx ok\n");
116	#endif
117	
118	  if (syscall(SYS_faccessat, AT_FDCWD, path, F_OK, 0) != 0) {
119	    printf("FILEIO: faccessat failed\n");
120	    _exit(1);
121	  }
122	  printf("FILEIO: faccessat ok\n");
123	
124	  char cwd[256];
125	  long cwdlen = syscall(SYS_getcwd, cwd, sizeof cwd);
126	  if (cwdlen <= 0) {
127	    printf("FILEIO: getcwd failed\n");
128	    _exit(1);
129	  }
130	  printf("FILEIO: getcwd ok len=%ld\n", cwdlen);
131	
132	  char linkbuf[16];
133	  long rl = syscall(SYS_readlinkat, AT_FDCWD, path, linkbuf, sizeof linkbuf);
134	  if (rl >= 0 || errno != EINVAL) {
135	    printf("FILEIO: readlinkat unexpected result %ld errno=%d\n", rl, errno);
136	    _exit(1);
137	  }
138	  printf("FILEIO: readlinkat correctly EINVAL\n");
139	
140	  int dfd = open(".", O_RDONLY | O_DIRECTORY);
141	  if (dfd >= 0) {
142	    char dbuf[64];
143	    errno = 0;
144	    long gd = syscall(SYS_getdents64, dfd, dbuf, sizeof dbuf);
145	    if (gd >= 0 || errno != ENOSYS) {
146	      printf("FILEIO: getdents64 unexpected result %ld errno=%d\n", gd, errno);
147	      _exit(1);
148	    }
149	    printf("FILEIO: getdents64 correctly ENOSYS\n");
150	    close(dfd);
151	  } else {
152	    printf("FILEIO: open(.) O_DIRECTORY failed, skipping getdents64 probe\n");
153	  }
154	
155	  printf("file io ok\n");
156	  _exit(0);
157	}
